      this.shakeAmt = 0;
      this.flameT = 0;
      this.camFocus = new Vector3(34, 0, 34);
      this.ui = new UI(this);
      this.pad = new Pad(this);
      this.touch = new Touch(this);
      this.clock = new Clock();
