      this.menuMode = true;
      this.creating = true;
      this.creation = { cls: "Knight", cape: CLASSES.Knight.cape, hooded: false, name: "", helm: true, gear: 0, tint: "#ffffff", height: 1, capeOn: true, pet: "fox", petSpecies: "fox", petName: "Pip", tab: "class", skin: "#ffffff", ...CLASS_DETAILS.Knight };
      const L = G.level;
      const spot = L.startPos.clone();
      this.podium = new Group();
      this.podium.position.copy(spot);
      const disc = new Mesh(new CylinderGeometry(1.3, 1.45, 0.25, 40), new MeshStandardMaterial({ color: 3813926, roughness: 0.8, metalness: 0.2 }));
      disc.position.y = 0.12;
      disc.receiveShadow = true;
      const rim = new Mesh(new TorusGeometry(1.32, 0.05, 8, 48), new MeshStandardMaterial({ color: 14201434, emissive: 9071136, emissiveIntensity: 0.8, metalness: 0.8, roughness: 0.3 }));
      rim.rotation.x = Math.PI / 2;
      rim.position.y = 0.25;
      const key = new SpotLight(16770752, 22, 14, 0.6, 0.6, 1.2);
      key.position.set(2.5, 6, 5);
      key.target.position.set(0, 1, 0);
      this.podium.add(disc, rim, key, key.target);
