      this.preview.applyLook(cls, s);
      this.preview.dress(starterKit(s), s, cls);
      if (this.previewPet) this.podium.remove(this.previewPet);
      const psp = PET_SPECIES[s.petSpecies] ? s.petSpecies : "fox";
