      let pos = L.startPos.clone();
      if (kind === "dungeon" && arrive === "up") pos = L.downPos.clone().add(new Vector3(1.5, 0, 1.5));
      if (kind === "town" && arrive === "portal") {
        pos = L.portalPos.clone().add(new Vector3(0, 0, 2));
        this.emerge = 0.7;
      }
      if (arrive === "resume" && loc && kind === "town") pos = new Vector3(loc.x, 0, loc.z);
      if (!L.walkable(pos)) pos = L.toWorld(...L.nearestFloor(...L.cellOf(pos)));
